// The page chrome - the breadcrumbs, the big application title and the button
// beside it - can be slid up out of the way to hand the whole window over to
// whatever is being read. The state lives here rather than in App.tsx so that
// an application panel can drive it, and put the button that brings it back
// somewhere that suits what it is showing, without importing App and closing an
// import cycle.
//
// Hiding is deliberately not sticky: the button that brings the chrome back
// belongs to the panel that hid it and leaves with it, so both App (on the way
// to another application) and useChromeToggle (on the way out) clear it.

import * as React from 'react';

export type Chrome = {
    hidden: boolean;
    setHidden: (v: boolean) => void;
};

export const ChromeContext = React.createContext<Chrome>({
    hidden: false,
    setHidden: () => { },
});

export function useChrome(): Chrome {
    return React.useContext(ChromeContext);
}

// For a panel that owns a show/hide control: the same chrome, with the promise
// that it is left showing when the panel goes away.
export function useChromeToggle(): Chrome {
    const chrome = useChrome();
    const { setHidden } = chrome;
    React.useEffect(() => () => setHidden(false), [setHidden]);
    return chrome;
}
