// ---------------------------------------------------------------------------
// The tree
// ---------------------------------------------------------------------------

type TreeNode = {
    name: string;
    path: string;
    isDir: boolean;
    children: TreeNode[];
    files: number; // org files at or under this node
};

function splitPath(p: string): string[] {
    return p.split(/[\\/]/).filter(s => s !== '');
}

export function baseName(path: string): string {
    const parts = splitPath(path);
    return parts.length > 0 ? parts[parts.length - 1] : path;
}

function dirName(path: string): string {
    const i = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    return i <= 0 ? '' : path.slice(0, i);
}

// The directory every file is under, so the tree starts where the files differ
// rather than at the filesystem root.
function commonPrefix(files: string[]): string[] {
    if (files.length === 0) return [];
    let pre = splitPath(dirName(files[0]));
    for (const f of files.slice(1)) {
        const parts = splitPath(dirName(f));
        let i = 0;
        while (i < pre.length && i < parts.length && pre[i] === parts[i]) i++;
        pre = pre.slice(0, i);
        if (pre.length === 0) break;
    }
    return pre;
}

function buildTree(files: string[]): TreeNode {
    const pre = commonPrefix(files);
    const absolute = files.length > 0 && files[0].startsWith('/');
    const rootPath = (absolute ? '/' : '') + pre.join('/');
    const root: TreeNode = { name: pre.length > 0 ? pre[pre.length - 1] : '/', path: rootPath, isDir: true, children: [], files: 0 };
    for (const f of files) {
        const parts = splitPath(f).slice(pre.length);
        let cur = root;
        cur.files++;
        for (let i = 0; i < parts.length; i++) {
            const last = i === parts.length - 1;
            const path = last ? f : cur.path + (cur.path.endsWith('/') ? '' : '/') + parts[i];
            let next = cur.children.find(c => c.name === parts[i] && c.isDir === !last);
            if (!next) {
                next = { name: parts[i], path, isDir: !last, children: [], files: 0 };
                cur.children.push(next);
            }
            next.files++;
            cur = next;
        }
    }
    const sortRec = (n: TreeNode) => {
        n.children.sort((a, b) => {
            if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
            return a.name.localeCompare(b.name);
        });
        n.children.forEach(sortRec);
    };
    sortRec(root);
    return root;
}

// Every word of the search has to turn up somewhere in the path, which is what
// makes "roblox work log" find ian/roblox/worklog.org.
function matches(path: string, terms: string[]): boolean {
    if (terms.length === 0) return true;
    const hay = path.toLowerCase();
    return terms.every(t => hay.indexOf(t) >= 0);
}

// ---------------------------------------------------------------------------
// Following a link clicked inside the rendered page
// ---------------------------------------------------------------------------

function normalize(path: string): string {
    const out: string[] = [];
    for (const part of splitPath(path)) {
        if (part === '.') continue;
        if (part === '..') {
            out.pop();
            continue;
        }
        out.push(part);
    }
    return (path.startsWith('/') ? '/' : '') + out.join('/');
}

// The html exporter rewrites a link to another org file as a link to the .html
// next to it, so that is undone here before the path is looked for.
function resolveHref(href: string, fromFile: string, allFiles: string[]): { file: string; heading: string } | null {
    let raw = href.trim();
    if (raw === '' || raw.startsWith('#')) return null;
    if (/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(raw) || raw.startsWith('mailto:')) return null;
    raw = raw.replace(/^file:/, '');
    let path = raw;
    let heading = '';
    const sep = raw.indexOf('::');
    if (sep >= 0) {
        path = raw.slice(0, sep);
        heading = raw.slice(sep + 2);
        // "*Heading" names a heading by its text, which is what the viewer can
        // scroll to. "#custom-id" names one by a property the exported page does
        // not carry, so there is nothing to look for and the file is opened at
        // the top instead.
        if (heading.startsWith('*')) heading = heading.slice(1);
        else if (heading.startsWith('#')) heading = '';
    }
    if (path === '') return { file: fromFile, heading };
    if (path.endsWith('.html')) path = path.slice(0, -'.html'.length) + '.org';
    if (!/\.org$/i.test(path)) return null;
    const want = path.startsWith('/') ? normalize(path) : normalize(dirName(fromFile) + '/' + path);
    if (allFiles.indexOf(want) >= 0) return { file: want, heading };
    const base = baseName(want).toLowerCase();
    const hits = allFiles.filter(f => baseName(f).toLowerCase() === base);
    if (hits.length === 1) return { file: hits[0], heading };
    return null;
}

// ---------------------------------------------------------------------------
// One row of the backlink list
// ---------------------------------------------------------------------------

function endLabel(l: OrgLink, which: 'From' | 'To'): string {
    const e = l[which];
    if (e.Filename === '') return l.Raw;
    if (e.Headline !== '') return e.Headline;
    return baseName(e.Filename);
}

function LinkRow({ link, side, onGo }: { link: OrgLink; side: 'in' | 'out' | 'internal'; onGo: (file: string, heading: string) => void }) {
    // An incoming link is read from its source; an outgoing one from its target.
    const jumpEnd = side === 'in' ? link.From : link.To;
    const canGo = jumpEnd.Filename !== '';
    const title = side === 'in' ? endLabel(link, 'From') : endLabel(link, 'To');
    const where = side === 'in' ? link.From : link.To;
    const olp = (where.Olp || []).join(' › ');
    return (
        <ListItem>
            <ListItemButton
                disabled={!canGo}
                onClick={() => canGo && onGo(jumpEnd.Filename, jumpEnd.Headline)}
                sx={{ alignItems: 'flex-start' }}
            >
                <ListItemDecorator sx={{ alignSelf: 'flex-start', mt: '3px', minInlineSize: 26 }}>
                    {link.Broken ? (
                        <LinkOffIcon sx={{ fontSize: 15, color: 'danger.400' }} />
                    ) : side === 'in' ? (
                        <CallReceivedIcon sx={{ fontSize: 15, color: 'primary.400' }} />
                    ) : side === 'out' ? (
                        <CallMadeIcon sx={{ fontSize: 15, color: 'success.400' }} />
                    ) : (
                        <LoopIcon sx={{ fontSize: 15, color: 'warning.400' }} />
                    )}
                </ListItemDecorator>
                <ListItemContent sx={{ minWidth: 0 }}>
                    <Typography level="body-sm" sx={{ fontWeight: 600, overflowWrap: 'anywhere' }}>
                        {title}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', overflowWrap: 'anywhere' }}>
                        {side === 'in'
                            ? `${baseName(link.From.Filename)}:${link.From.Line + 1}`
                            : `line ${link.From.Line + 1}${link.To.Filename !== '' ? ` → ${baseName(link.To.Filename)}` : ''}`}
                        {olp !== '' ? ` · ${olp}` : ''}
                    </Typography>
                    {link.Desc !== '' && (
                        <Typography level="body-xs" sx={{ color: 'text.secondary', fontStyle: 'italic', overflowWrap: 'anywhere' }}>
                            “{link.Desc}”
                        </Typography>
                    )}
                    <Box sx={{ display: 'flex', gap: 0.5, mt: 0.25, flexWrap: 'wrap' }}>
                        <Chip size="sm" variant="soft" color={link.Broken ? 'danger' : 'neutral'} sx={{ fontSize: 10 }}>
                            {link.Kind}
                        </Chip>
                        <Tooltip size="sm" title={link.Raw} placement="top">
                            <Chip size="sm" variant="plain" color="neutral" sx={{ fontSize: 10, fontFamily: 'monospace', maxWidth: 180 }}>
                                {link.Raw}
                            </Chip>
                        </Tooltip>
                    </Box>
                </ListItemContent>
            </ListItemButton>
        </ListItem>
    );
}

function LinkSection({ title, links, side, onGo }: { title: string; links: OrgLink[]; side: 'in' | 'out' | 'internal'; onGo: (f: string, h: string) => void }) {
    if (links.length === 0) return null;
    return (
        <Box sx={{ mb: 0.5 }}>
            <Typography level="title-sm" sx={{ px: 1.5, pt: 1, color: 'text.secondary' }}>
                {title} <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>({links.length})</Typography>
            </Typography>
            <List size="sm" sx={{ '--ListItem-radius': '6px', '--ListItem-paddingY': '4px' }}>
                {links.map((l, i) => (
                    <LinkRow key={`${l.From.Filename}:${l.From.Line}:${l.Raw}:${i}`} link={l} side={side} onGo={onGo} />
                ))}
            </List>
        </Box>
    );
}

// ---------------------------------------------------------------------------
// The tab
// ---------------------------------------------------------------------------

const PANEL_WIDTH = 420;
const TREE_WIDTH = 320;
// The gap between the tree and the page, carried by the tree's own box so that
// it closes along with it rather than leaving a strip of nothing behind.
const TREE_GAP = 16;

// What the page over on the right is showing.
type View = 'html' | 'source' | 'sheet';

export default function Files() {
    // The page chrome and the row of buttons over the file slide up together,
    // off the one button, so that a file can have the whole window.
    const chrome = useChromeToggle();
    const [allFiles, setAllFiles] = React.useState<string[]>([]);
    const [stats, setStats] = React.useState<Map<string, LinkFileStat>>(new Map());
    // The org files the server reads as D&D character sheets.
    const [dndFiles, setDndFiles] = React.useState<Set<string>>(new Set());
    const [loadingFiles, setLoadingFiles] = React.useState(true);
    const [filter, setFilter] = React.useState('');
    const [expanded, setExpanded] = React.useState<Set<string>>(new Set());
    const [treeOpen, setTreeOpen] = React.useState(true);
    const [selected, setSelected] = React.useState<string | null>(null);
    const [view, setView] = React.useState<View>('html');
    const [wrap, setWrap] = React.useState(false);
    const [html, setHtml] = React.useState('');
    const [raw, setRaw] = React.useState('');
    const [sheetHtml, setSheetHtml] = React.useState('');
    const [loadingPage, setLoadingPage] = React.useState(false);
    // Bumped by the refresh button to fetch the showing view again.
    const [reloadKey, setReloadKey] = React.useState(0);
    const [error, setError] = React.useState('');

    const [panelOpen, setPanelOpen] = React.useState(false);
    const [backlinks, setBacklinks] = React.useState<Backlinks | null>(null);
    const [graph, setGraph] = React.useState<LinkGraphResult | null>(null);
    const [loadingLinks, setLoadingLinks] = React.useState(false);
    const [depth, setDepth] = React.useState(2);
    const [scope, setScope] = React.useState<'file' | 'heading'>('file');

    // The theme the page is rendered with, from the settings menu.
    const htmlTheme = useHtmlTheme();

    const iframeRef = React.useRef<HTMLIFrameElement>(null);
    // The heading to scroll to once the page that holds it has rendered.
    const pendingHeading = React.useRef<string>('');

    const loadFiles = React.useCallback(async () => {
        setLoadingFiles(true);
        const [files, st, chars] = await Promise.all([
            ODb.getFiles(),
            ODb.getLinkStats(),
            // A server with the dnd module turned off answers with nothing,
            // which is exactly the answer this wants: no file offers a sheet.
            ODb.getDndCharacters(),
        ]);
        const list = files || [];
        setAllFiles(list);
        const m = new Map<string, LinkFileStat>();
        for (const s of (st && st.Files) || []) m.set(s.Filename, s);
        setStats(m);
        setDndFiles(new Set((Array.isArray(chars) ? chars : []).map(c => c.filename)));
        setLoadingFiles(false);
    }, []);

    React.useEffect(() => {
        loadFiles();
    }, [loadFiles]);

    const loadLinks = React.useCallback(async (file: string, d: number, sc: 'file' | 'heading') => {
        setLoadingLinks(true);
        const [bl, g] = await Promise.all([ODb.getBacklinks(file), ODb.getLinkGraph(file, d, sc)]);
        setBacklinks(bl && bl.Filename !== undefined ? bl : null);
        setGraph(g && g.Ok !== undefined ? g : null);
        setLoadingLinks(false);
    }, []);

    // Open a file. Which view it opens in is the file's own business: a
    // character sheet opens as a sheet, anything else keeps whatever view you
    // were already reading in, so following a link out of the source of one
    // file lands in the source of the next.
    const openFile = React.useCallback((file: string, heading: string = '') => {
        setSelected(file);
        pendingHeading.current = heading;
        setError('');
        setView(prev => (dndFiles.has(file) ? 'sheet' : prev === 'sheet' ? 'html' : prev));
        // Reveal the file in the tree, wherever it was reached from.
        setExpanded(prev => {
            const next = new Set(prev);
            const parts = splitPath(dirName(file));
            let acc = file.startsWith('/') ? '' : '';
            for (const p of parts) {
                acc = acc + '/' + p;
                next.add(acc);
            }
            return next;
        });
    }, [dndFiles]);

    // Fetch whatever the showing view needs. The token is what keeps a slow
    // answer for a file you have already clicked away from off the screen.
    const loadToken = React.useRef(0);
    const loadView = React.useCallback(async (file: string, v: View, theme: string) => {
        const token = ++loadToken.current;
        setError('');
        setLoadingPage(true);
        const res = v === 'html'
            ? await ODb.fileHtml(file, theme)
            : v === 'source'
                ? await ODb.getOrgFile(file)
                : await ODb.dndSheetHtml(file);
        if (token !== loadToken.current) return;
        if (res && res.Ok && res.Msg !== undefined) {
            if (v === 'html') setHtml(res.Msg);
            else if (v === 'source') setRaw(res.Msg);
            else setSheetHtml(res.Msg);
        } else {
            setError((res && res.Msg) || 'Could not read that file');
        }
        setLoadingPage(false);
    }, []);

    // Only the exported page depends on the html theme, so changing it while
    // reading the source does not go and fetch the source again.
    const themeDep = view === 'html' ? htmlTheme : '';

    React.useEffect(() => {
        if (selected === null) return;
        setHtml('');
        setRaw('');
        setSheetHtml('');
        loadView(selected, view, themeDep);
    }, [selected, view, themeDep, reloadKey, loadView]);

    // The links for whichever file is showing.
    React.useEffect(() => {
        if (selected === null) return;
        if (!panelOpen) return;
        loadLinks(selected, depth, scope);
    }, [selected, panelOpen, depth, scope, loadLinks]);

    // Whether the open file is one the server reads as a character sheet, which
    // is what puts the third button over the page.
    const isDnd = selected !== null && dndFiles.has(selected);
    // Only ever hidden with a file open: the button that brings it back is
    // drawn over the page, and with nothing open there is no page to draw on.
    const headerHidden = chrome.hidden && selected !== null;

    // The document in the frame: the exported page or the character sheet. The
    // source view is not a document and draws itself.
    const shown = view === 'sheet' ? sheetHtml : html;

    // Backlink counts for the button, without waiting for the panel to be opened.
    const selectedStat = selected !== null ? stats.get(selected) : undefined;
    const inCount = backlinks !== null && backlinks.Filename === selected
        ? (backlinks.In || []).length
        : (selectedStat ? selectedStat.In : 0);

    // Scroll to a heading once the rendered page is in the frame. The exporter
    // gives headings random ids, so they are found by their text instead.
    const onFrameLoad = React.useCallback(() => {
        const frame = iframeRef.current;
        if (!frame) return;
        const doc = frame.contentDocument;
        if (!doc) return;
        // The character sheet is an application rather than an exported page:
        // its links are its own and it is not scrolled to a heading.
        if (view === 'sheet') return;

        const want = pendingHeading.current;
        pendingHeading.current = '';
        if (want !== '') {
            const target = want.trim().toLowerCase();
            const heads = Array.from(doc.querySelectorAll('h1,h2,h3,h4,h5,h6'));
            const hit =
                heads.find(h => (h.textContent || '').trim().toLowerCase() === target) ||
                heads.find(h => (h.textContent || '').trim().toLowerCase().indexOf(target) >= 0);
            if (hit) {
                hit.scrollIntoView({ block: 'start' });
                (hit as HTMLElement).style.transition = 'background-color 1.2s';
                (hit as HTMLElement).style.backgroundColor = 'rgba(255, 213, 79, 0.45)';
                window.setTimeout(() => { (hit as HTMLElement).style.backgroundColor = 'transparent'; }, 1400);
            }
        }

        // A link to another org file is followed here rather than by the frame,
        // which would only navigate to a path the server does not serve.
        doc.addEventListener('click', (ev: Event) => {
            const a = (ev.target as Element | null)?.closest?.('a');
            if (!a) return;
            const href = a.getAttribute('href') || '';
            if (/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(href) || href.startsWith('mailto:')) {
                ev.preventDefault();
                window.open(href, '_blank', 'noopener');
                return;
            }
            const hit = selected !== null ? resolveHref(href, selected, allFiles) : null;
            if (hit) {
                ev.preventDefault();
                openFile(hit.file, hit.heading);
            }
        }, true);
    }, [allFiles, selected, openFile, view]);

    const terms = React.useMemo(() => filter.toLowerCase().split(/\s+/).filter(t => t !== ''), [filter]);
    const shownFiles = React.useMemo(() => allFiles.filter(f => matches(f, terms)), [allFiles, terms]);
    const tree = React.useMemo(() => buildTree(shownFiles), [shownFiles]);
    const searching = terms.length > 0;

    const toggleDir = (path: string) => {
        setExpanded(prev => {
            const next = new Set(prev);
            if (next.has(path)) next.delete(path);
            else next.add(path);
            return next;
        });
    };

    // A file row, with whatever the link counts have to say about it.
    const renderFile = (n: TreeNode, indent: number) => {
        const st = stats.get(n.path);
        return (
            <ListItem key={n.path} sx={{ '--ListItem-paddingLeft': `${8 + indent * 12}px` }}>
                <ListItemButton selected={selected === n.path} onClick={() => openFile(n.path)}>
                    <ListItemDecorator sx={{ minInlineSize: 24 }}>
                        <DescriptionOutlinedIcon sx={{ fontSize: 15, color: 'text.tertiary' }} />
                    </ListItemDecorator>
                    <ListItemContent sx={{ minWidth: 0 }}>
                        <Typography level="body-sm" sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {n.name}
                        </Typography>
                    </ListItemContent>
                    {st !== undefined && (st.In > 0 || st.Out > 0 || st.Broken > 0) && (
                        <Box sx={{ display: 'flex', gap: 0.25, flexShrink: 0 }}>
                            {st.In > 0 && (
                                <Tooltip size="sm" title={`${st.In} link${st.In === 1 ? '' : 's'} in`}>
                                    <Chip size="sm" variant="soft" color="primary" sx={{ fontSize: 10, minHeight: 16 }}>{st.In}</Chip>
                                </Tooltip>
                            )}
                            {st.Out > 0 && (
                                <Tooltip size="sm" title={`${st.Out} link${st.Out === 1 ? '' : 's'} out`}>
                                    <Chip size="sm" variant="soft" color="success" sx={{ fontSize: 10, minHeight: 16 }}>{st.Out}</Chip>
                                </Tooltip>
                            )}
                            {st.Broken > 0 && (
                                <Tooltip size="sm" title={`${st.Broken} broken link${st.Broken === 1 ? '' : 's'}`}>
                                    <Chip size="sm" variant="soft" color="danger" sx={{ fontSize: 10, minHeight: 16 }}>{st.Broken}</Chip>
                                </Tooltip>
                            )}
                        </Box>
                    )}
                </ListItemButton>
            </ListItem>
        );
    };

    const renderNodes = (kids: TreeNode[], indent: number): React.ReactNode[] => {
        const out: React.ReactNode[] = [];
        for (const n of kids) {
            if (!n.isDir) {
                out.push(renderFile(n, indent));
                continue;
            }
            const open = searching || expanded.has(n.path);
            out.push(
                <ListItem key={n.path} sx={{ '--ListItem-paddingLeft': `${8 + indent * 12}px` }}>
                    <ListItemButton onClick={() => toggleDir(n.path)}>
                        <ListItemDecorator sx={{ minInlineSize: 24 }}>
                            {open
                                ? <FolderOpenIcon sx={{ fontSize: 16, color: 'warning.400' }} />
                                : <FolderIcon sx={{ fontSize: 16, color: 'warning.400' }} />}
                        </ListItemDecorator>
                        <ListItemContent sx={{ minWidth: 0 }}>
                            <Typography level="body-sm" sx={{ fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                {n.name}
                            </Typography>
                        </ListItemContent>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', flexShrink: 0 }}>{n.files}</Typography>
                    </ListItemButton>
                </ListItem>
            );
            if (open) out.push(...renderNodes(n.children, indent + 1));
        }
        return out;
    };

    // Clicking a node of the graph opens whatever it stands for.
    const onPickGraphNode = (n: LinkGraphNode) => {
        if (n.Filename === '') return;
        openFile(n.Filename, n.Kind === 'heading' ? n.Label : '');
    };

    return (
        // The links panel is parked off the right edge when it is closed, so the
        // row it sits in has to clip rather than letting the page grow to hold
        // it. Clip rather than hide: hidden still leaves the row a scroll
        // container, and a click on any of the buttons over the page is then
        // enough for the browser to scroll the parked panel into view and take
        // the file tree off the left edge with it.
        <Box sx={{ display: 'flex', flex: 1, minHeight: 0, position: 'relative', overflow: 'clip' }}>
            {/* The tree, in a box that closes to nothing and takes the tree with
                it. The box is what animates; the tree inside keeps its width the
                whole way, so the rows slide out of sight rather than being
                squeezed narrower and narrower on the way. */}
            <Box
                sx={{
                    flexShrink: 0,
                    width: treeOpen ? TREE_WIDTH + TREE_GAP : 0,
                    pr: treeOpen ? `${TREE_GAP}px` : 0,
                    overflow: 'hidden',
                    transition: 'width 0.28s ease, padding-right 0.28s ease',
                }}
            >
            <Sheet
                variant="outlined"
                sx={{ width: TREE_WIDTH, height: '100%', flexShrink: 0, borderRadius: 'sm', display: 'flex', flexDirection: 'column', minHeight: 0 }}
            >
                <Box sx={{ p: 1, display: 'flex', gap: 1, alignItems: 'center' }}>
                    <Input
                        size="sm"
                        placeholder="Search files"
                        value={filter}
                        onChange={e => setFilter(e.target.value)}
                        startDecorator={<SearchIcon />}
                        sx={{ flex: 1 }}
                    />
                    <Tooltip size="sm" title="Collapse everything">
                        <IconButton size="sm" variant="outlined" color="neutral" onClick={() => setExpanded(new Set())}>
                            <UnfoldLessIcon />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="Reload the file list and link counts">
                        <IconButton size="sm" variant="outlined" color="neutral" onClick={loadFiles}>
                            <RefreshIcon />
                        </IconButton>
                    </Tooltip>
                </Box>
                <Box sx={{ px: 1, pb: 0.5 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {loadingFiles ? 'Loading…' : `${shownFiles.length} of ${allFiles.length} files · ${tree.path}`}
                    </Typography>
                </Box>
                <Box sx={{ overflow: 'auto', flex: 1, minHeight: 0 }}>
                    {loadingFiles && <Box sx={{ p: 2, textAlign: 'center' }}><CircularProgress size="sm" /></Box>}
                    {!loadingFiles && shownFiles.length === 0 && (
                        <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>No files match that search.</Typography>
                    )}
                    <List size="sm" sx={{ '--ListItem-radius': '6px', '--ListItem-paddingY': '2px', '--List-gap': '0px' }}>
                        {renderNodes(tree.children, 0)}
                    </List>
                </Box>
            </Sheet>
            </Box>

            {/* The rendered file */}
            <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: 1, minHeight: 0 }}>
                {/* This row is here whether or not a file is open, because the
                    button that brings the tree back lives on it. It slides up
                    out of the way with the page chrome above it - same grid row
                    trick, so it closes under its own height - and the button
                    that brings both back is parked over the top of the page. */}
                <Box
                    sx={{
                        display: 'grid',
                        gridTemplateRows: headerHidden ? '0fr' : '1fr',
                        mb: headerHidden ? -1 : 0,
                        flexShrink: 0,
                        transition: 'grid-template-rows 0.28s ease, margin-bottom 0.28s ease',
                    }}
                >
                <Box
                    sx={{
                        overflow: 'hidden',
                        minHeight: 0,
                        opacity: headerHidden ? 0 : 1,
                        transform: headerHidden ? 'translateY(-8px)' : 'none',
                        // Hidden rather than merely clipped, once it has
                        // finished sliding, so that tabbing through the page
                        // does not land on buttons nobody can see.
                        visibility: headerHidden ? 'hidden' : 'visible',
                        transition: `opacity 0.2s ease, transform 0.28s ease, visibility 0s linear ${headerHidden ? '0.28s' : '0s'}`,
                    }}
                >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
                    <Tooltip size="sm" title={treeOpen ? 'Hide the file tree' : 'Show the file tree'}>
                        <IconButton
                            size="sm"
                            variant={treeOpen ? 'outlined' : 'solid'}
                            color="neutral"
                            onClick={() => setTreeOpen(o => !o)}
                            sx={{ flexShrink: 0 }}
                        >
                            {treeOpen ? <MenuOpenIcon /> : <MenuIcon />}
                        </IconButton>
                    </Tooltip>
                    {selected !== null && (
                        <>
                            <Typography level="title-md" sx={{ flexShrink: 0 }}>{baseName(selected)}</Typography>
                            <Tooltip size="sm" title={selected} placement="bottom-start">
                                <Typography
                                    level="body-xs"
                                    sx={{ color: 'text.tertiary', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
                                >
                                    {dirName(selected)}
                                </Typography>
                            </Tooltip>
                            <Box sx={{ ml: 'auto', display: 'flex', gap: 1, flexShrink: 0, alignItems: 'center' }}>
                                <ToggleButtonGroup
                                    size="sm"
                                    value={view}
                                    onChange={(_e, v) => v && setView(v as View)}
                                >
                                    <Button value="html" startDecorator={<ArticleOutlinedIcon />}>Rendered</Button>
                                    <Button value="source" startDecorator={<CodeIcon />}>Org</Button>
                                    {isDnd && (
                                        <Button value="sheet" startDecorator={<CasinoIcon />}>Sheet</Button>
                                    )}
                                </ToggleButtonGroup>
                                {view === 'source' && (
                                    <Tooltip size="sm" title={wrap ? 'Stop wrapping long lines' : 'Wrap long lines'}>
                                        <IconButton
                                            size="sm"
                                            variant={wrap ? 'solid' : 'outlined'}
                                            color="neutral"
                                            onClick={() => setWrap(w => !w)}
                                        >
                                            <WrapTextIcon />
                                        </IconButton>
                                    </Tooltip>
                                )}
                                <Tooltip size="sm" title="Read this file again">
                                    <IconButton size="sm" variant="outlined" color="neutral" onClick={() => setReloadKey(k => k + 1)}>
                                        <RefreshIcon />
                                    </IconButton>
                                </Tooltip>
                                <Badge badgeContent={inCount > 0 ? inCount : 0} invisible={inCount === 0} size="sm" color="primary">
                                    <Button
                                        size="sm"
                                        variant={panelOpen ? 'solid' : 'outlined'}
                                        color="primary"
                                        startDecorator={<HubIcon />}
                                        onClick={() => setPanelOpen(o => !o)}
                                    >
                                        Links
                                    </Button>
                                </Badge>
                                <Tooltip size="sm" title="Hide this bar and the page title">
                                    <IconButton
                                        size="sm"
                                        variant="outlined"
                                        color="neutral"
                                        onClick={() => chrome.setHidden(true)}
                                    >
                                        <KeyboardDoubleArrowUpIcon />
                                    </IconButton>
                                </Tooltip>
                            </Box>
                        </>
                    )}
                </Box>
                </Box>
                </Box>
                {selected === null && (
                    <Sheet variant="soft" sx={{ flex: 1, borderRadius: 'sm', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Box sx={{ textAlign: 'center', color: 'text.tertiary' }}>
                            <ArticleOutlinedIcon sx={{ fontSize: 48, opacity: 0.4 }} />
                            <Typography level="body-sm">Pick a file to read it.</Typography>
                        </Box>
                    </Sheet>
                )}
                {selected !== null && (
                    <>
                        {error !== '' && <Alert size="sm" color="danger" variant="soft">{error}</Alert>}
                        <Sheet
                            variant="outlined"
                            // A stylesheet that names no background leaves the
                            // exported page transparent, so the frame is given a
                            // ground to suit its theme once there is a page in it.
                            // The source view paints its own, so it is left alone.
                            sx={{
                                flex: 1, minHeight: 0, borderRadius: 'sm', overflow: 'hidden', position: 'relative',
                                bgcolor: view === 'source'
                                    ? 'transparent'
                                    : shown === ''
                                        ? 'background.level1'
                                        : view === 'sheet'
                                            ? '#ffffff'
                                            : (isDarkHtmlTheme(htmlTheme) ? '#14161a' : '#ffffff'),
                            }}
                        >
                            {/* The way back, parked over the top corner of
                                the page itself and faded down until it is
                                pointed at, so that it costs the reading almost
                                nothing. It steps aside when the links panel
                                slides over that corner. */}
                            {headerHidden && (
                                <Tooltip size="sm" title="Show the toolbar and title again" placement="left">
                                    <IconButton
                                        size="sm"
                                        variant="soft"
                                        color="neutral"
                                        onClick={() => chrome.setHidden(false)}
                                        sx={{
                                            position: 'absolute',
                                            top: 6,
                                            right: panelOpen ? PANEL_WIDTH + 6 : 6,
                                            zIndex: 2,
                                            opacity: 0.7,
                                            transition: 'opacity 0.2s ease, right 0.28s ease',
                                            '&:hover': { opacity: 1 },
                                        }}
                                    >
                                        <KeyboardDoubleArrowDownIcon />
                                    </IconButton>
                                </Tooltip>
                            )}
                            {loadingPage && (
                                <Box sx={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1 }}>
                                    <CircularProgress size="sm" />
                                </Box>
                            )}
                            {view === 'source' && raw !== '' && (
                                <OrgSource text={raw} wrap={wrap} scrollTo={pendingHeading.current} />
                            )}
                            {view !== 'source' && shown !== '' && (
                                <iframe
                                    // Keyed by view so that switching between
                                    // the exported page and the character sheet
                                    // builds a new frame rather than handing the
                                    // old one a different document to run.
                                    key={view}
                                    ref={iframeRef}
                                    title={view === 'sheet' ? 'character sheet' : 'org file'}
                                    srcDoc={shown}
                                    onLoad={onFrameLoad}
                                    style={{ width: '100%', height: '100%', border: 'none', display: 'block' }}
                                />
                            )}
                        </Sheet>
                    </>
                )}
            </Box>

            {/* The links panel, over the page rather than squeezing it */}
            <Sheet
                variant="outlined"
                sx={{
                    position: 'absolute',
                    top: 0,
                    right: 0,
                    height: '100%',
                    width: PANEL_WIDTH,
                    maxWidth: '92%',
                    display: 'flex',
                    flexDirection: 'column',
                    minHeight: 0,
                    borderRadius: 'sm',
                    boxShadow: 'lg',
                    zIndex: 30,
                    transform: panelOpen ? 'translateX(0)' : `translateX(calc(100% + 24px))`,
                    transition: 'transform 0.28s ease',
                }}
            >
                <Box sx={{ p: 1.5, pb: 1, display: 'flex', alignItems: 'center', gap: 1 }}>
                    <HubIcon sx={{ fontSize: 18, color: 'primary.400' }} />
                    <Box sx={{ minWidth: 0, flex: 1 }}>
                        <Typography level="title-sm">Links</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {selected !== null ? baseName(selected) : '—'}
                        </Typography>
                    </Box>
                    {loadingLinks && <CircularProgress size="sm" />}
                    <IconButton size="sm" variant="plain" color="neutral" onClick={() => setPanelOpen(false)}>
                        <CloseIcon />
                    </IconButton>
                </Box>
                <Divider />

                {/* The listing */}
                <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
                    {backlinks !== null && !backlinks.Ok && backlinks.Msg !== '' && (
                        <Alert size="sm" color="warning" variant="soft" sx={{ m: 1 }}>{backlinks.Msg}</Alert>
                    )}
                    {backlinks !== null && backlinks.Ok && (
                        <>
                            <LinkSection
                                title="Linked from"
                                links={backlinks.In || []}
                                side="in"
                                onGo={(f, h) => openFile(f, h)}
                            />
                            <LinkSection
                                title="Within this file"
                                links={backlinks.Internal || []}
                                side="internal"
                                onGo={(f, h) => openFile(f, h)}
                            />
                            <LinkSection
                                title="Links from here"
                                links={backlinks.Out || []}
                                side="out"
                                onGo={(f, h) => openFile(f, h)}
                            />
                            {(backlinks.In || []).length === 0 &&
                                (backlinks.Out || []).length === 0 &&
                                (backlinks.Internal || []).length === 0 && (
                                    <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>
                                        Nothing links to this file, and it links nowhere yet.
                                    </Typography>
                                )}
                        </>
                    )}
                </Box>

                {/* The graph, underneath */}
                <Divider />
                <Box sx={{ p: 1, pb: 0.5, display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                    <Typography level="title-sm" sx={{ flex: 1 }}>Graph</Typography>
                    <ToggleButtonGroup
                        size="sm"
                        value={scope}
                        onChange={(_e, v) => v && setScope(v as 'file' | 'heading')}
                    >
                        <Button value="file">Files</Button>
                        <Button value="heading">Headings</Button>
                    </ToggleButtonGroup>
                    <ToggleButtonGroup
                        size="sm"
                        value={String(depth)}
                        onChange={(_e, v) => v && setDepth(Number(v))}
                    >
                        <Button value="1">1</Button>
                        <Button value="2">2</Button>
                        <Button value="3">3</Button>
                    </ToggleButtonGroup>
                </Box>
                <Box sx={{ px: 0.5, pb: 0.5 }}>
                    {/* No `selected` here on purpose: the center node already
                        reads as the center from its colour and glow, and marking
                        it selected would dim everything that is not next to it. */}
                    <LinkGraph data={graph} height={300} onPick={onPickGraphNode} />
                </Box>
            </Sheet>
        </Box>
    );
}
