import * as React from 'react';
import Box from '@mui/joy/Box';
import Button from '@mui/joy/Button';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import Input from '@mui/joy/Input';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Table from '@mui/joy/Table';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import IconButton from '@mui/joy/IconButton';
import Chip from '@mui/joy/Chip';
import FilterAltIcon from '@mui/icons-material/FilterAlt';
import SearchIcon from '@mui/icons-material/Search';
import KeyboardArrowRightIcon from '@mui/icons-material/KeyboardArrowRight';
import KeyboardArrowLeftIcon from '@mui/icons-material/KeyboardArrowLeft';
import * as Db from '../db';
import { ActiveClockBanner, useRunningClock } from './activeclock';

type ClockEntry = {
  headline: string;
  filename: string;
  level: number;
  mins: number;
};

function formatDuration(mins: number): string {
  const h = Math.floor(mins / 60);
  const m = Math.round(mins % 60);
  if (h > 0 && m > 0) return `${h}h ${m}m`;
  if (h > 0) return `${h}h`;
  return `${m}m`;
}

const BLOCK_OPTIONS = [
  { value: 'today', label: 'Today' },
  { value: 'yesterday', label: 'Yesterday' },
  { value: 'thisweek', label: 'This Week' },
  { value: 'lastweek', label: 'Last Week' },
  { value: 'thismonth', label: 'This Month' },
  { value: 'lastmonth', label: 'Last Month' },
];

const PAGE_SIZE = 25;

export default function ClockReport() {
  const [block, setBlock] = React.useState('today');
  // The clock that is running, asked for on a timer of its own so that the
  // banner keeps up with a clock started in another tab.
  const { clock, refresh: refreshClock } = useRunningClock();
  const [entries, setEntries] = React.useState<ClockEntry[]>([]);
  const [totalMin, setTotalMin] = React.useState(0);
  const [loading, setLoading] = React.useState(false);

  // Filters
  const [headlineFilter, setHeadlineFilter] = React.useState('');
  const [filenameFilter, setFilenameFilter] = React.useState('');
  const [minLevel, setMinLevel] = React.useState<number | null>(null);
  const [maxLevel, setMaxLevel] = React.useState<number | null>(null);

  // Pagination
  const [page, setPage] = React.useState(0);

  const fetchReport = React.useCallback(async () => {
    setLoading(true);
    try {
      const data = await Db.ODb.getClockReport(block);
      if (data && !Array.isArray(data) && data.entries) {
        setEntries(data.entries || []);
        setTotalMin(data.totalMin || 0);
      } else {
        setEntries([]);
        setTotalMin(0);
      }
    } catch (e) {
      console.error('Failed to fetch clock report:', e);
      setEntries([]);
      setTotalMin(0);
    }
    setLoading(false);
  }, [block]);

  React.useEffect(() => {
    fetchReport();
  }, [fetchReport]);

  // Derived filter values
  const allFilenames = React.useMemo(() => {
    const fnames = new Set<string>();
    entries.forEach(e => fnames.add(e.filename.replace(/^.*\//, '')));
    return Array.from(fnames).sort();
  }, [entries]);

  // Filtered entries
  const filtered = React.useMemo(() => {
    return entries.filter(e => {
      if (headlineFilter && !e.headline.toLowerCase().includes(headlineFilter.toLowerCase())) return false;
      if (filenameFilter && !e.filename.replace(/^.*\//, '').toLowerCase().includes(filenameFilter.toLowerCase())) return false;
      if (minLevel !== null && e.level < minLevel) return false;
      if (maxLevel !== null && e.level > maxLevel) return false;
      return true;
    });
  }, [entries, headlineFilter, filenameFilter, minLevel, maxLevel]);

  // Filtered total
  const filteredTotal = React.useMemo(() => {
    return filtered.reduce((sum, e) => sum + e.mins, 0);
  }, [filtered]);

  // Pagination
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const pagedEntries = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  React.useEffect(() => { setPage(0); }, [headlineFilter, filenameFilter, minLevel, maxLevel, block]);

  return (
    <React.Fragment>
      {/* What is being timed right now. Above the filters rather than in the
          table: the report is a picture of time already written into the
          files, and the clock that is running has not been written yet - it
          would be a row whose number changed while you read the total. */}
      <Box sx={{ mb: 1.5 }}>
        <ActiveClockBanner clock={clock} onStopped={() => { refreshClock(); fetchReport(); }} />
      </Box>

      {/* Filter bar */}
      <Sheet
        className="ClockReportFilterBar"
        variant="outlined"
        sx={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 1.5,
          p: 2,
          borderRadius: 'sm',
          alignItems: 'flex-end',
        }}
      >
        <FormControl size="sm">
          <FormLabel>Time Block</FormLabel>
          <Select
            size="sm"
            value={block}
            onChange={(_e, val) => { if (val) setBlock(val); }}
            sx={{ minWidth: 140 }}
          >
            {BLOCK_OPTIONS.map(opt => (
              <Option key={opt.value} value={opt.value}>{opt.label}</Option>
            ))}
          </Select>
        </FormControl>

        <FormControl size="sm">
          <FormLabel>Headline</FormLabel>
          <Input
            size="sm"
            placeholder="Filter headline..."
            startDecorator={<SearchIcon />}
            value={headlineFilter}
            onChange={(e) => setHeadlineFilter(e.target.value)}
            sx={{ minWidth: 160 }}
          />
        </FormControl>

        <FormControl size="sm">
          <FormLabel>File</FormLabel>
          <Input
            size="sm"
            placeholder="Filter file..."
            value={filenameFilter}
            onChange={(e) => setFilenameFilter(e.target.value)}
            sx={{ minWidth: 140 }}
          />
        </FormControl>

        <FormControl size="sm">
          <FormLabel>Min Level</FormLabel>
          <Input
            size="sm"
            type="number"
            placeholder="Min"
            value={minLevel ?? ''}
            onChange={(e) => setMinLevel(e.target.value ? parseInt(e.target.value) : null)}
            sx={{ width: 70 }}
          />
        </FormControl>

        <FormControl size="sm">
          <FormLabel>Max Level</FormLabel>
          <Input
            size="sm"
            type="number"
            placeholder="Max"
            value={maxLevel ?? ''}
            onChange={(e) => setMaxLevel(e.target.value ? parseInt(e.target.value) : null)}
            sx={{ width: 70 }}
          />
        </FormControl>

        <Button size="sm" variant="outlined" color="neutral" onClick={fetchReport} startDecorator={<FilterAltIcon />}>
          Refresh
        </Button>
      </Sheet>

      {/* Summary */}
      <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mt: 1, mb: 0.5 }}>
        <Typography level="body-sm" sx={{ fontWeight: 'bold' }}>
          {BLOCK_OPTIONS.find(o => o.value === block)?.label || block}
        </Typography>
        <Chip size="sm" variant="soft" color="primary">
          {filtered.length} {filtered.length === 1 ? 'entry' : 'entries'}
        </Chip>
        <Chip size="sm" variant="soft" color="success">
          Total: {formatDuration(filteredTotal)}
        </Chip>
        {filtered.length !== entries.length && (
          <Chip size="sm" variant="soft" color="neutral">
            Unfiltered total: {formatDuration(totalMin)}
          </Chip>
        )}
      </Box>

      {/* Table */}
      <Sheet
        className="ClockReportTableContainer"
        variant="outlined"
        sx={{
          width: '100%',
          borderRadius: 'sm',
          flexShrink: 1,
          overflow: 'auto',
          minHeight: 0,
        }}
      >
        <Table
          aria-labelledby="clockReportTable"
          stickyHeader
          hoverRow
          sx={{
            '--TableCell-headBackground': 'var(--joy-palette-background-level1)',
            '--Table-headerUnderlineThickness': '1px',
            '--TableRow-hoverBackground': 'var(--joy-palette-background-level1)',
            '--TableCell-paddingY': '4px',
            '--TableCell-paddingX': '8px',
          }}
        >
          <thead>
            <tr>
              <th style={{ width: 50, padding: '12px 6px' }}>Lvl</th>
              <th style={{ padding: '12px 6px' }}>Headline</th>
              <th style={{ width: 180, padding: '12px 6px' }}>File</th>
              <th style={{ width: 100, padding: '12px 6px', textAlign: 'right' }}>Duration</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={4}><Typography level="body-sm" sx={{ textAlign: 'center', py: 2 }}>Loading...</Typography></td></tr>
            ) : pagedEntries.length === 0 ? (
              <tr><td colSpan={4}><Typography level="body-sm" sx={{ textAlign: 'center', py: 2 }}>No clock entries found</Typography></td></tr>
            ) : (
              pagedEntries.map((entry, i) => (
                <tr key={`${entry.filename}-${entry.headline}-${i}`}>
                  <td>
                    <Typography level="body-xs">{entry.level}</Typography>
                  </td>
                  <td>
                    <Typography level="body-xs" sx={{ pl: `${(entry.level - 1) * 12}px` }}>
                      {entry.headline}
                    </Typography>
                  </td>
                  <td>
                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '10px', color: 'text.tertiary' }}>
                      {entry.filename.replace(/^.*\//, '')}
                    </Typography>
                  </td>
                  <td style={{ textAlign: 'right' }}>
                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                      {formatDuration(entry.mins)}
                    </Typography>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </Sheet>

      {/* Pagination */}
      {totalPages > 1 && (
        <Box
          sx={{
            pt: 1,
            gap: 1,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <IconButton
            size="sm"
            color="neutral"
            variant="outlined"
            disabled={page === 0}
            onClick={() => setPage(p => p - 1)}
          >
            <KeyboardArrowLeftIcon />
          </IconButton>
          <Typography level="body-sm">
            Page {page + 1} of {totalPages}
          </Typography>
          <IconButton
            size="sm"
            color="neutral"
            variant="outlined"
            disabled={page >= totalPages - 1}
            onClick={() => setPage(p => p + 1)}
          >
            <KeyboardArrowRightIcon />
          </IconButton>
        </Box>
      )}
    </React.Fragment>
  );
}
