// User settings that live in this browser rather than on the server.
//
// They are kept in localStorage under one key, read once at startup and written
// back on every change. Components read them with the useSetting hook, which
// re-renders everyone watching a value when any tab or any part of the app
// changes it - a plain module variable would leave the other readers stale.

export type UserSettings = {
    // The theme the files view renders org files with. Two values are not
    // stylesheet names: "auto" follows the app's own light/dark mode, and
    // "file" leaves the file's own #+HTML_THEME alone.
    htmlTheme: string;

    // The kanban board that was open last. The boards themselves live on the
    // server, because a board names a stored query that lives there too and the
    // pair of them would come apart in another browser; which one you were
    // looking at is about this browser and stays here.
    kanbanBoard: string;

    // Which renderer the gantt view draws with: "mermaid" for the diagram
    // mermaid makes of the server's gantt source, or one of "react", "vis" and
    // "google", which are drawn from /gantt/tasks and can be edited. All four
    // are the same schedule - this is a preference about reading it, so it
    // lives in the browser.
    ganttRenderer: GanttRenderer;

    // What a gantt bar's colour means: its state, its keyword, who it is
    // assigned to, its lane, how far along it is, or the value of one property.
    // Kept per browser like the renderer, because it is about reading the plan
    // rather than about the plan.
    ganttColorBy: string;

    // The property `ganttColorBy: 'property'` colours by, e.g. "PRIORITY".
    ganttColorProp: string;

    // The colour scheme the Org source view reads in: a key from ORG_THEMES,
    // or "auto" to follow the app's own light and dark.
    orgTheme: string;

    // Which engine draws the mind map. All three draw the same tree; this is
    // about how you want to read it, so it stays in the browser.
    mindEngine: MindEngine;
};

// Four renderers, one schedule. Only mermaid is read-only: it is drawn from
// the exporter's source, which says what a bar is but not which heading.
export type GanttRenderer = 'mermaid' | 'react' | 'vis' | 'google';

// Four engines, one tree. Only mermaid is a picture rather than a map: its
// nodes cannot be moved, which is exactly why it is the one worth exporting.
export type MindEngine = 'elixir' | 'jsmind' | 'markmap' | 'mermaid';

export const HTML_THEME_AUTO = 'auto';
export const HTML_THEME_FILE = 'file';

// Dark by default: the files view is read inside the app, and a white page in a
// dark app is the thing this setting exists to stop happening.
export const defaultSettings: UserSettings = {
    htmlTheme: 'dark',
    kanbanBoard: '',
    // Mermaid by default: it is the chart this view has always drawn.
    ganttRenderer: 'mermaid',
    ganttColorBy: 'state',
    ganttColorProp: 'PRIORITY',
    orgTheme: 'auto',
    // Mind Elixir by default: it is the one that looks like a mind map and the
    // one you can think with.
    mindEngine: 'elixir',
};

const STORAGE_KEY = 'worg.settings';

function load(): UserSettings {
    try {
        const raw = window.localStorage.getItem(STORAGE_KEY);
        if (!raw) return { ...defaultSettings };
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return { ...defaultSettings };
        // Merged onto the defaults so a setting added later still has a value.
        return { ...defaultSettings, ...parsed };
    } catch {
        return { ...defaultSettings };
    }
}

let current: UserSettings = load();

type Listener = (s: UserSettings) => void;
const listeners = new Set<Listener>();

export function getSettings(): UserSettings {
    return current;
}

export function setSetting<K extends keyof UserSettings>(key: K, value: UserSettings[K]) {
    if (current[key] === value) return;
    current = { ...current, [key]: value };
    try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(current));
    } catch {
        // A browser with storage turned off still gets the setting for this session.
    }
    listeners.forEach(l => l(current));
}

export function subscribeSettings(l: Listener): () => void {
    listeners.add(l);
    return () => { listeners.delete(l); };
}

// The same settings changed in another tab.
if (typeof window !== 'undefined') {
    window.addEventListener('storage', (ev: StorageEvent) => {
        if (ev.key !== STORAGE_KEY) return;
        current = load();
        listeners.forEach(l => l(current));
    });
}

// Resolve the html theme setting to the name the exporter wants, or '' to let
// the file keep its own theme. mode is the app's current color scheme.
export function resolveHtmlTheme(setting: string, mode: string | undefined): string {
    if (setting === HTML_THEME_FILE) return '';
    if (setting === HTML_THEME_AUTO) return mode === 'light' ? 'default' : 'dark';
    return setting;
}

// The themes that paint a dark page. This matters because a stylesheet that
// never names a background leaves the exported page transparent, and the frame
// it sits in is what shows through - so the ground behind the frame has to be
// the one the page expects. Add a name here when you add a dark stylesheet.
const DARK_HTML_THEMES = new Set(['dark']);

export function isDarkHtmlTheme(theme: string): boolean {
    return DARK_HTML_THEMES.has(theme);
}
