// --- what is being typed ----------------------------------------------------

export interface WordAt {
    // The word under the caret, and where it starts.
    word: string;
    start: number;
}

// The identifier the caret is in or at the end of. Only letters count: a
// function name has nothing else in it, and stopping at anything else is what
// keeps `IsTodo() && Has` from offering completions for the whole line.
export function wordAt(text: string, caret: number): WordAt {
    let start = caret;
    while (start > 0 && /[A-Za-z]/.test(text.charAt(start - 1))) start -= 1;
    return { word: text.slice(start, caret), start };
}

// Whether the caret is inside a quoted string, where a function name means
// nothing and suggesting one would be noise.
export function inString(text: string, caret: number): boolean {
    let single = false;
    let double = false;
    for (let i = 0; i < caret && i < text.length; i++) {
        const c = text.charAt(i);
        if (c === '\\') { i += 1; continue; }
        if (c === '"' && !single) double = !double;
        else if (c === "'" && !double) single = !single;
    }
    return single || double;
}

// The functions a half-typed word could become.
//
// Prefix first and in the catalogue's order, then the ones that merely contain
// it: somebody typing `Tag` means `HasTags` sooner than they mean
// `InTagGroup`, but both are worth offering.
export function completionsFor(word: string): QueryFn[] {
    if (word === '') return [];
    const w = word.toLowerCase();
    const starts = QUERY_FUNCTIONS.filter(f => f.name.toLowerCase().indexOf(w) === 0);
    const contains = QUERY_FUNCTIONS.filter(
        f => f.name.toLowerCase().indexOf(w) > 0,
    );
    return starts.concat(contains);
}

// What to offer, given the whole box and where the caret is.
export function completionsAt(text: string, caret: number): { from: number; word: string; options: QueryFn[] } {
    if (inString(text, caret)) return { from: caret, word: '', options: [] };
    const { word, start } = wordAt(text, caret);
    return { from: start, word, options: completionsFor(word) };
}

// Putting a chosen function in. The name, its brackets, and the caret left
// where the next thing gets typed: inside the brackets when it takes
// arguments, after them when it does not.
export function applyCompletion(
    text: string, from: number, caret: number, fn: QueryFn,
): { text: string; caret: number } {
    const before = text.slice(0, from);
    const after = text.slice(caret);
    // Brackets that are already there are not doubled.
    const already = after.charAt(0) === '(';
    const insert = already ? fn.name : `${fn.name}()`;
    const at = fn.args === ''
        ? before.length + insert.length + (already ? 0 : 0)
        : before.length + fn.name.length + 1;
    return {
        text: before + insert + after,
        caret: fn.args === '' && !already ? before.length + insert.length : at,
    };
}

// --- brackets and quotes ----------------------------------------------------

const PAIRS: Record<string, string> = { '(': ')', '[': ']', '{': '}', '"': '"', "'": "'" };
const CLOSERS = new Set([')', ']', '}', '"', "'"]);

export interface PairEdit {
    text: string;
    caret: number;
}

// What typing one character should do, or null to let it be typed normally.
//
// Three rules, and the third is the one that makes the other two bearable:
//
// 1. An opener inserts its partner and leaves the caret between them.
// 2. Typing a closer when that closer is already under the caret steps over it
//    rather than adding a second one - otherwise auto-pairing means deleting a
//    bracket every time you finish a call by hand.
// 3. A quote is both, so it only opens when the caret is not already on one.
export function typePair(text: string, start: number, end: number, typed: string): PairEdit | null {
    const selected = text.slice(start, end);

    // Typing a closer that is already there: step over it.
    if (CLOSERS.has(typed) && selected === '' && text.charAt(start) === typed) {
        // For a quote this is also how it closes, which is why it comes first.
        return { text, caret: start + 1 };
    }

    const partner = PAIRS[typed];
    if (!partner) return null;

    // Around a selection: wrap it, and keep it selected-ish by leaving the
    // caret after what was wrapped.
    if (selected !== '') {
        return {
            text: text.slice(0, start) + typed + selected + partner + text.slice(end),
            caret: end + 2,
        };
    }

    // A quote in the middle of a word is an apostrophe, not the start of a
    // string.
    if ((typed === '"' || typed === "'") && /[A-Za-z0-9]/.test(text.charAt(start - 1))) {
        return null;
    }

    return {
        text: text.slice(0, start) + typed + partner + text.slice(end),
        caret: start + 1,
    };
}

// Backspace between a pair takes both, which is what somebody who did not want
// the pair is reaching for.
export function backspacePair(text: string, start: number, end: number): PairEdit | null {
    if (start !== end || start === 0) return null;
    const before = text.charAt(start - 1);
    const after = text.charAt(start);
    if (PAIRS[before] && PAIRS[before] === after) {
        return { text: text.slice(0, start - 1) + text.slice(start + 1), caret: start - 1 };
    }
    return null;
}

// --- putting a regular expression into a query -------------------------------

// A string that is going inside "..." in an expression.
export function quoteForQuery(re: string): string {
    return re.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

// The query with a content match added, or the plain content match when there
// was no query. Written as a separate clause rather than folded into whatever
// was typed, so turning it off again takes it away cleanly.
export function withContentMatch(query: string, re: string): string {
    const clean = (re || '').trim();
    if (clean === '') return query;
    const clause = `MatchContent("${quoteForQuery(clean)}")`;
    const q = (query || '').trim();
    return q === '' ? clause : `(${q}) && ${clause}`;
}
