// The mind map tab.
//
// A saved query's headings, put back into the shape they have in their files
// and drawn as a map. Three engines draw it - mermaid, mind-elixir and jsMind -
// from one tree built in mindmap.ts, so the choice is about how you want to
// read the plan rather than about what is in it. Whichever is chosen follows
// the app's light and dark, because a white map in a dark app is the thing
// people notice before anything else about it.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Input from '@mui/joy/Input';
import Chip from '@mui/joy/Chip';
import Tooltip from '@mui/joy/Tooltip';
import CircularProgress from '@mui/joy/CircularProgress';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import Alert from '@mui/joy/Alert';
import Dropdown from '@mui/joy/Dropdown';
import Menu from '@mui/joy/Menu';
import MenuButton from '@mui/joy/MenuButton';
import MenuItem from '@mui/joy/MenuItem';
import Switch from '@mui/joy/Switch';
import { useColorScheme } from '@mui/joy/styles';

import SearchIcon from '@mui/icons-material/Search';
import RefreshIcon from '@mui/icons-material/Refresh';
import SaveIcon from '@mui/icons-material/Save';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import PaletteIcon from '@mui/icons-material/Palette';
import ZoomInIcon from '@mui/icons-material/ZoomIn';
import ZoomOutIcon from '@mui/icons-material/ZoomOut';
import CenterFocusStrongIcon from '@mui/icons-material/CenterFocusStrong';
import UnfoldMoreIcon from '@mui/icons-material/UnfoldMore';
import UnfoldLessIcon from '@mui/icons-material/UnfoldLess';
import OpenInFullIcon from '@mui/icons-material/OpenInFull';
import CloseFullscreenIcon from '@mui/icons-material/CloseFullscreen';

import { ODb } from '../db';
import {
    MindLook, MindNode, MindRow, MindDirection, NodeStyle, Density,
    MIND_PALETTES, NODE_STYLES, DENSITIES, DIRECTIONS, paletteOf, densityOf,
    buildTree, countNodes, depthOf, trimDepth, filterTree, flatten,
    searchTerms, baseName,
} from '../mindmap';
import { contrastText, paletteFor, shade } from '../ganttstyle';
import { useChromeToggle } from '../ChromeContext';
import { useSetting } from '../useSettings';

import MermaidMind, { MermaidMindHandle } from './MermaidMind';

// The other three are heavy and none is wanted until it is chosen.
const MindElixir = React.lazy(() => import('./MindElixir'));
const JsMindMap = React.lazy(() => import('./JsMindMap'));
const MarkMap = React.lazy(() => import('./MarkMap'));

interface StoredQuery {
    name: string;
    query: string;
}

// The engine names live in settings.ts, because the choice is stored there.
import type { MindEngine as Engine } from '../settings';

const ENGINES: { value: Engine; label: string; hint: string }[] = [
    { value: 'elixir', label: 'Mind Elixir', hint: 'Drag branches about, fold them, edit a node — the map as a thinking surface' },
    { value: 'jsmind', label: 'jsMind', hint: 'Boxes and branches, left and right of the root — the easiest to read at a glance' },
    { value: 'markmap', label: 'Markmap', hint: 'No boxes: the words with a curve to each, spreading right — best for a deep tree' },
    { value: 'mermaid', label: 'Mermaid', hint: 'A drawing rather than a map: fixed, tidy, and the one that goes into a document' },
];

type ColorBy = 'branch' | 'depth' | 'status';

const COLOR_MODES: { value: ColorBy; label: string; hint: string }[] = [
    { value: 'branch', label: 'Branch', hint: 'One hue per branch off the root, lightening as it goes out — the classic mind map' },
    { value: 'depth', label: 'Depth', hint: 'One hue per level, so how deep a node sits is the thing you can see' },
    { value: 'status', label: 'Keyword', hint: 'One hue per todo keyword, wherever the heading sits' },
];

// What colour a node is drawn.
//
// Branch is the default because it is what makes a wide map readable: a branch
// and everything hanging off it share a hue, so the eye follows one line out
// from the middle instead of reading every box. It lightens with depth so that
// a long branch does not become one block of colour.
function makeColorFor(mode: ColorBy, dark: boolean, keywords: string[], paletteKey: string) {
    const p = paletteOf(paletteKey);
    const hue = (i: number) => p.hues[((i % p.hues.length) + p.hues.length) % p.hues.length];
    const root = dark ? p.rootDark : p.rootLight;
    const keyIndex = new Map<string, number>();
    keywords.forEach((k, i) => keyIndex.set(k, i));
    return (n: MindNode): string => {
        if (n.depth === 0) return root;
        if (mode === 'depth') return hue(n.depth - 1);
        if (mode === 'status') {
            if (n.status === '') return dark ? '#4b5563' : '#9aa4b2';
            return hue(keyIndex.get(n.status) || 0);
        }
        const base = hue(Math.max(0, n.branch));
        // Two steps of lightening and then flat: past that it would be closer
        // to the page than to the branch it belongs to.
        return shade(base, Math.min(2, n.depth - 1) * (dark ? 0.12 : -0.1));
    };
}

export default function MindMap() {
    const chrome = useChromeToggle();
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const palette = paletteFor(dark ? 'dark' : 'light');

    const [engine, setEngine] = useSetting('mindEngine');
    const [queries, setQueries] = React.useState<StoredQuery[]>([]);
    const [selected, setSelected] = React.useState<string>('');
    const [rows, setRows] = React.useState<MindRow[] | null>(null);
    const [loading, setLoading] = React.useState(false);
    const [loadingQueries, setLoadingQueries] = React.useState(true);
    const [error, setError] = React.useState('');
    const [title, setTitle] = React.useState('');
    const [filter, setFilter] = React.useState('');
    const [maxDepth, setMaxDepth] = React.useState(0);
    const [openTo, setOpenTo] = React.useState(99);
    const [show, setShow] = React.useState({ status: true, priority: true, tags: false });
    const [editable, setEditable] = React.useState(true);
    const [curve, setCurve] = React.useState(true);
    const [colorBy, setColorBy] = React.useState<ColorBy>('branch');
    // The styling group. Kept together because it is one question - what the
    // map should look like - asked in five parts.
    const [paletteKey, setPaletteKey] = React.useState('classic');
    const [nodeStyle, setNodeStyle] = React.useState<NodeStyle>('filled');
    const [density, setDensity] = React.useState<Density>('cosy');
    const [direction, setDirection] = React.useState<MindDirection>('side');
    const [alignment, setAlignment] = React.useState<'root' | 'nodes'>('nodes');
    const [picked, setPicked] = React.useState<MindNode | null>(null);

    const mermaidRef = React.useRef<MermaidMindHandle>(null);
    const elixirRef = React.useRef<any>(null);
    const jsmindRef = React.useRef<any>(null);
    const markmapRef = React.useRef<any>(null);

    React.useEffect(() => {
        let alive = true;
        ODb.getStoredQueries()
            .then(r => { if (alive) { setQueries(r || []); setLoadingQueries(false); } })
            .catch(() => { if (alive) { setQueries([]); setLoadingQueries(false); } });
        return () => { alive = false; };
    }, []);

    const generate = React.useCallback(async (name: string) => {
        const q = queries.find(x => x.name === name);
        if (!q) return;
        setLoading(true);
        setError('');
        setPicked(null);
        try {
            // The saved query stands on its own: no base filter, because a map
            // is as likely to be of a reference tree as of a list of tasks.
            const res = await ODb.query(q.query, false, new AbortController().signal, '');
            const list = Array.isArray(res) ? res : [];
            setRows(list);
            setTitle(t => (t === '' ? name : t));
            if (list.length === 0) setError('That query found no headings.');
        } catch (e: any) {
            setRows(null);
            setError((e && e.message) || 'Could not run that query.');
        } finally {
            setLoading(false);
        }
    }, [queries]);

    // The whole tree, then the one actually drawn: filtered, then trimmed.
    const full = React.useMemo(
        () => (rows ? buildTree(rows, title || selected || 'Mind map') : null),
        [rows, title, selected],
    );
    const deepest = React.useMemo(() => (full ? depthOf(full) : 1), [full]);
    const root = React.useMemo(() => {
        if (!full) return null;
        const terms = searchTerms(filter);
        const found = filterTree(full, terms);
        if (!found) return null;
        return maxDepth > 0 ? trimDepth(found, maxDepth) : found;
    }, [full, filter, maxDepth]);

    // The keywords actually on the map, in the order the outline meets them,
    // so colouring by keyword gives the same keyword the same hue every time.
    const keywords = React.useMemo(() => {
        if (!full) return [];
        const seen: string[] = [];
        for (const n of flatten(full)) {
            if (n.status !== '' && seen.indexOf(n.status) < 0) seen.push(n.status);
        }
        return seen;
    }, [full]);

    const colorFor = React.useMemo(
        () => makeColorFor(colorBy, dark, keywords, paletteKey),
        [colorBy, dark, keywords, paletteKey],
    );
    const dense = React.useMemo(() => densityOf(density), [density]);
    const textOn = React.useCallback((bg: string) => contrastText(bg), []);

    const look: MindLook = React.useMemo(() => {
        const p = paletteOf(paletteKey);
        return {
        dark,
        palette: p.hues.slice(0, 6),
        rootBg: dark ? p.rootDark : p.rootLight,
        accent: p.hues[0],
        line: dark ? '#5a6472' : '#9aa4b2',
        text: dark ? '#c9d1d9' : '#24292f',
        ground: palette.background,
        panel: dark ? '#1a1d23' : '#ffffff',
        border: dark ? '#2b3038' : '#dfe3e8',
        };
    }, [dark, palette.background, paletteKey]);

    const nodes = root ? countNodes(root) : 0;
    const hidden = full && root ? countNodes(full) - nodes : 0;

    const onPick = React.useCallback((id: string) => {
        if (!full) return;
        const stack: MindNode[] = [full];
        while (stack.length > 0) {
            const n = stack.pop()!;
            if (n.id === id) { setPicked(n); return; }
            n.children.forEach(c => stack.push(c));
        }
    }, [full]);

    const saveSvg = async () => {
        let svg = '';
        if (engine === 'mermaid') svg = mermaidRef.current ? mermaidRef.current.svg() : '';
        else if (engine === 'elixir') svg = elixirRef.current ? await elixirRef.current.svg() : '';
        else if (engine === 'markmap') svg = markmapRef.current ? markmapRef.current.svg() : '';
        else svg = jsmindRef.current ? jsmindRef.current.svg() : '';
        if (svg === '') return;
        const name = (title || 'mindmap').replace(/[^A-Za-z0-9_-]/g, '_');
        const blob = new Blob([svg], { type: 'image/svg+xml' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${name}.svg`;
        a.click();
        URL.revokeObjectURL(url);
    };

    const zoom = (by: number) => {
        if (engine === 'elixir' && elixirRef.current) elixirRef.current.zoom(by);
        if (engine === 'jsmind' && jsmindRef.current) jsmindRef.current.zoom(by);
        if (engine === 'markmap' && markmapRef.current) markmapRef.current.zoom(by);
    };
    const fit = () => {
        if (engine === 'elixir' && elixirRef.current) elixirRef.current.fit();
        if (engine === 'jsmind' && jsmindRef.current) jsmindRef.current.fit();
        if (engine === 'markmap' && markmapRef.current) markmapRef.current.fit();
    };
    const foldAll = (open: boolean) => {
        setOpenTo(open ? 99 : 1);
        if (engine === 'jsmind' && jsmindRef.current) jsmindRef.current.expandAll(open);
    };

    const live = engine !== 'mermaid';
    // markmap draws no boxes, so the node style and the direction have nothing
    // to act on there; saying so is better than leaving a control that does
    // nothing when it is chosen.
    const boxes = engine === 'elixir' || engine === 'jsmind';
    const current = ENGINES.find(e => e.value === engine) || ENGINES[0];

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, gap: 1 }}>
            {/* What to draw */}
            <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 1.25 }}>
                <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 1.25, flexWrap: 'wrap' }}>
                    <FormControl size="sm" sx={{ minWidth: 220 }}>
                        <FormLabel>Query</FormLabel>
                        {loadingQueries ? (
                            <CircularProgress size="sm" />
                        ) : queries.length === 0 ? (
                            <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                                No saved queries yet — add one in the Saved Queries tab.
                            </Typography>
                        ) : (
                            <Select
                                size="sm"
                                placeholder="Pick one"
                                value={selected === '' ? null : selected}
                                onChange={(_, v) => {
                                    const name = (v as string) || '';
                                    setSelected(name);
                                    setTitle(name);
                                    if (name !== '') generate(name);
                                }}
                            >
                                {queries.map(q => (
                                    <Option key={q.name} value={q.name}>
                                        {q.name}
                                        <Typography level="body-xs" sx={{ ml: 1, color: 'text.tertiary', fontFamily: 'monospace' }}>
                                            {q.query.length > 36 ? q.query.slice(0, 36) + '…' : q.query}
                                        </Typography>
                                    </Option>
                                ))}
                            </Select>
                        )}
                    </FormControl>

                    <FormControl size="sm" sx={{ minWidth: 170 }}>
                        <FormLabel>Drawn by</FormLabel>
                        <Dropdown>
                            <MenuButton
                                size="sm"
                                variant="outlined"
                                color="neutral"
                                startDecorator={<AccountTreeIcon sx={{ fontSize: 16 }} />}
                                sx={{ fontWeight: 'md', justifyContent: 'flex-start' }}
                            >
                                {current.label}
                            </MenuButton>
                            <Menu size="sm" placement="bottom-start" sx={{ maxWidth: 340 }}>
                                {ENGINES.map(e => (
                                    <MenuItem
                                        key={e.value}
                                        selected={e.value === engine}
                                        onClick={() => setEngine(e.value)}
                                        sx={{ display: 'block' }}
                                    >
                                        <Typography level="body-sm" sx={{ fontWeight: 'lg' }}>{e.label}</Typography>
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{e.hint}</Typography>
                                    </MenuItem>
                                ))}
                            </Menu>
                        </Dropdown>
                    </FormControl>

                    <FormControl size="sm" sx={{ minWidth: 130 }}>
                        <FormLabel>Colour by</FormLabel>
                        <Select
                            size="sm"
                            value={colorBy}
                            onChange={(_, v) => setColorBy((v as ColorBy) || 'branch')}
                            renderValue={o => (COLOR_MODES.find(m => m.value === o?.value) || COLOR_MODES[0]).label}
                        >
                            {COLOR_MODES.map(m => (
                                <Option key={m.value} value={m.value} sx={{ display: 'block' }}>
                                    <Typography level="body-sm" sx={{ fontWeight: 'lg' }}>{m.label}</Typography>
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{m.hint}</Typography>
                                </Option>
                            ))}
                        </Select>
                    </FormControl>

                    <FormControl size="sm" sx={{ minWidth: 110 }}>
                        <FormLabel>Style</FormLabel>
                        <Dropdown>
                            <MenuButton
                                size="sm"
                                variant="outlined"
                                color="neutral"
                                startDecorator={<PaletteIcon sx={{ fontSize: 16 }} />}
                                sx={{ fontWeight: 'md', justifyContent: 'flex-start' }}
                            >
                                {paletteOf(paletteKey).label}
                            </MenuButton>
                            {/* A menu rather than five more boxes on the bar.
                                They are one question - what the map should look
                                like - and most of them are set once and left. */}
                            <Menu size="sm" placement="bottom-start" sx={{ p: 1.5, minWidth: 260 }}>
                                <Typography level="body-xs" sx={{ fontWeight: 'lg', textTransform: 'uppercase', letterSpacing: '0.07em', color: 'text.tertiary', mb: 0.5 }}>
                                    Palette
                                </Typography>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, mb: 1.5 }}>
                                    {MIND_PALETTES.map(p => (
                                        <Box
                                            key={p.key}
                                            onClick={() => setPaletteKey(p.key)}
                                            sx={{
                                                display: 'flex', alignItems: 'center', gap: 1, px: 1, py: 0.75,
                                                borderRadius: 'sm', cursor: 'pointer',
                                                background: p.key === paletteKey ? 'var(--joy-palette-neutral-softBg)' : 'transparent',
                                                '&:hover': { background: 'var(--joy-palette-neutral-softHoverBg)' },
                                            }}
                                        >
                                            <Box sx={{ display: 'flex', flexShrink: 0, borderRadius: 'sm', overflow: 'hidden' }}>
                                                {p.hues.slice(0, 6).map(h => (
                                                    <Box key={h} sx={{ width: 11, height: 16, background: h }} />
                                                ))}
                                            </Box>
                                            <Box sx={{ minWidth: 0 }}>
                                                <Typography level="body-sm" sx={{ fontWeight: 'lg' }}>{p.label}</Typography>
                                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>{p.hint}</Typography>
                                            </Box>
                                        </Box>
                                    ))}
                                </Box>

                                {boxes && (
                                    <FormControl size="sm" sx={{ mb: 1 }}>
                                        <FormLabel>Nodes</FormLabel>
                                        <Select
                                            size="sm"
                                            value={nodeStyle}
                                            onChange={(_, v) => setNodeStyle((v as NodeStyle) || 'filled')}
                                            renderValue={o => (NODE_STYLES.find(n => n.value === o?.value) || NODE_STYLES[0]).label}
                                        >
                                            {NODE_STYLES.map(n => (
                                                <Option key={n.value} value={n.value} sx={{ display: 'block' }}>
                                                    <Typography level="body-sm" sx={{ fontWeight: 'lg' }}>{n.label}</Typography>
                                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{n.hint}</Typography>
                                                </Option>
                                            ))}
                                        </Select>
                                    </FormControl>
                                )}

                                <FormControl size="sm" sx={{ mb: 1 }}>
                                    <FormLabel>Spacing</FormLabel>
                                    <Select size="sm" value={density} onChange={(_, v) => setDensity((v as Density) || 'cosy')}>
                                        {DENSITIES.map(d => <Option key={d.value} value={d.value}>{d.label}</Option>)}
                                    </Select>
                                </FormControl>

                                {boxes && (
                                    <FormControl size="sm" sx={{ mb: 1 }}>
                                        <FormLabel>Spreads</FormLabel>
                                        <Select
                                            size="sm"
                                            value={direction}
                                            onChange={(_, v) => setDirection((v as MindDirection) || 'side')}
                                        >
                                            {DIRECTIONS.map(d => (
                                                <Option
                                                    key={d.value}
                                                    value={d.value}
                                                    // jsMind lays out both sides or one, and has no
                                                    // downwards of its own.
                                                    disabled={engine === 'jsmind' && d.value === 'down'}
                                                >
                                                    {d.label}
                                                </Option>
                                            ))}
                                        </Select>
                                    </FormControl>
                                )}

                                {engine === 'elixir' && (
                                    <FormControl size="sm">
                                        <FormLabel>Line up on</FormLabel>
                                        <Select
                                            size="sm"
                                            value={alignment}
                                            onChange={(_, v) => setAlignment((v as 'root' | 'nodes') || 'nodes')}
                                        >
                                            <Option value="nodes">Each other</Option>
                                            <Option value="root">The root</Option>
                                        </Select>
                                    </FormControl>
                                )}
                            </Menu>
                        </Dropdown>
                    </FormControl>

                    <FormControl size="sm" sx={{ minWidth: 150 }}>
                        <FormLabel>Title</FormLabel>
                        <Input
                            size="sm"
                            value={title}
                            onChange={e => setTitle(e.target.value)}
                            placeholder="The root's name"
                        />
                    </FormControl>

                    <FormControl size="sm" sx={{ minWidth: 170 }}>
                        <FormLabel>Find</FormLabel>
                        <Input
                            size="sm"
                            value={filter}
                            onChange={e => setFilter(e.target.value)}
                            startDecorator={<SearchIcon sx={{ fontSize: 16 }} />}
                            placeholder="Keep branches matching"
                        />
                    </FormControl>

                    <FormControl size="sm" sx={{ minWidth: 120 }}>
                        <FormLabel>Depth</FormLabel>
                        <Select
                            size="sm"
                            value={maxDepth}
                            onChange={(_, v) => setMaxDepth((v as number) ?? 0)}
                        >
                            <Option value={0}>All {deepest > 1 ? `(${deepest})` : ''}</Option>
                            {[1, 2, 3, 4, 5, 6].filter(d => d < deepest).map(d => (
                                <Option key={d} value={d}>{d} deep</Option>
                            ))}
                        </Select>
                    </FormControl>

                    <Box sx={{ display: 'flex', gap: 0.5, ml: 'auto', alignItems: 'center' }}>
                        {loading && <CircularProgress size="sm" />}
                        {rows !== null && (
                            <Tooltip size="sm" title={hidden > 0 ? `${hidden} more are filtered or below the depth` : 'Every heading the query found'}>
                                <Chip size="sm" variant="soft" color={hidden > 0 ? 'warning' : 'neutral'}>
                                    {nodes} node{nodes === 1 ? '' : 's'}
                                </Chip>
                            </Tooltip>
                        )}
                        <Tooltip size="sm" title="Run the query again">
                            <span>
                                <IconButton
                                    size="sm" variant="plain" disabled={selected === ''}
                                    onClick={() => generate(selected)}
                                >
                                    <RefreshIcon fontSize="small" />
                                </IconButton>
                            </span>
                        </Tooltip>
                        <Tooltip size="sm" title={chrome.hidden ? 'Show the title again' : 'Give the map the window'}>
                            <IconButton size="sm" variant="plain" onClick={() => chrome.setHidden(!chrome.hidden)}>
                                {chrome.hidden ? <CloseFullscreenIcon fontSize="small" /> : <OpenInFullIcon fontSize="small" />}
                            </IconButton>
                        </Tooltip>
                    </Box>
                </Box>

                {/* How it is drawn */}
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, flexWrap: 'wrap', mt: 1.25 }}>
                    {([
                        ['status', 'Keyword'],
                        ['priority', 'Priority'],
                        ['tags', 'Tags'],
                    ] as [keyof typeof show, string][]).map(([key, label]) => (
                        <Box key={key} sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                            <Switch
                                size="sm"
                                checked={show[key]}
                                onChange={e => setShow(s => ({ ...s, [key]: e.target.checked }))}
                            />
                            <Typography level="body-xs">{label}</Typography>
                        </Box>
                    ))}

                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <Switch size="sm" checked={curve} onChange={e => setCurve(e.target.checked)} />
                        <Typography level="body-xs">Curved branches</Typography>
                    </Box>

                    {live && (
                        <Tooltip size="sm" title="Let nodes be dragged, folded and renamed. Nothing is written back to the org files.">
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                <Switch size="sm" checked={editable} onChange={e => setEditable(e.target.checked)} />
                                <Typography level="body-xs">Rearrangeable</Typography>
                            </Box>
                        </Tooltip>
                    )}

                    <Box sx={{ display: 'flex', gap: 0.5, ml: 'auto' }}>
                        <Tooltip size="sm" title="Open every branch">
                            <IconButton size="sm" variant="plain" onClick={() => foldAll(true)}>
                                <UnfoldMoreIcon fontSize="small" />
                            </IconButton>
                        </Tooltip>
                        <Tooltip size="sm" title="Fold everything back to the first branches">
                            <IconButton size="sm" variant="plain" onClick={() => foldAll(false)}>
                                <UnfoldLessIcon fontSize="small" />
                            </IconButton>
                        </Tooltip>
                        {live && (
                            <>
                                <Tooltip size="sm" title="Zoom out"><IconButton size="sm" variant="plain" onClick={() => zoom(-0.15)}><ZoomOutIcon fontSize="small" /></IconButton></Tooltip>
                                <Tooltip size="sm" title="Zoom in"><IconButton size="sm" variant="plain" onClick={() => zoom(0.15)}><ZoomInIcon fontSize="small" /></IconButton></Tooltip>
                                <Tooltip size="sm" title="Put the root back in the middle"><IconButton size="sm" variant="plain" onClick={fit}><CenterFocusStrongIcon fontSize="small" /></IconButton></Tooltip>
                            </>
                        )}
                        <Tooltip size="sm" title="Save the map as an SVG">
                            <span>
                                <IconButton size="sm" variant="plain" disabled={!root} onClick={saveSvg}>
                                    <SaveIcon fontSize="small" />
                                </IconButton>
                            </span>
                        </Tooltip>
                    </Box>
                </Box>
            </Sheet>

            {error !== '' && (
                <Alert size="sm" variant="soft" color="warning">{error}</Alert>
            )}

            {picked && !picked.synthetic && (
                <Alert
                    size="sm"
                    variant="soft"
                    color="neutral"
                    endDecorator={
                        <Button size="sm" variant="plain" color="neutral" onClick={() => setPicked(null)}>Dismiss</Button>
                    }
                >
                    <Box sx={{ minWidth: 0 }}>
                        <Typography level="body-sm" sx={{ fontWeight: 'lg' }} noWrap>
                            {picked.status !== '' ? `${picked.status} ` : ''}{picked.text}
                        </Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {baseName(picked.file)}:{picked.line}
                            {picked.tags.length > 0 ? ` · :${picked.tags.join(':')}:` : ''}
                        </Typography>
                    </Box>
                </Alert>
            )}

            {/* The map */}
            <Sheet
                variant="outlined"
                sx={{
                    borderRadius: 'md', flex: 1, minHeight: 360, overflow: 'hidden',
                    background: palette.background,
                    position: 'relative',
                }}
            >
                {!root && !loading && (
                    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', p: 4, gap: 1 }}>
                        <AccountTreeIcon sx={{ fontSize: 40, color: 'text.tertiary' }} />
                        <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                            Pick a saved query to draw its headings as a map.
                        </Typography>
                    </Box>
                )}
                {root && (
                    <React.Suspense fallback={<Box sx={{ display: 'flex', justifyContent: 'center', p: 6 }}><CircularProgress /></Box>}>
                        {engine === 'markmap' && (
                            <MarkMap
                                ref={markmapRef}
                                root={root}
                                look={look}
                                colorFor={colorFor}
                                show={show}
                                openTo={openTo}
                                spacing={{ horizontal: dense.mainGapX, vertical: dense.gapY }}
                                onPick={onPick}
                            />
                        )}
                        {engine === 'mermaid' && (
                            <MermaidMind
                                ref={mermaidRef}
                                root={root}
                                look={look}
                                colorFor={colorFor}
                                textOn={textOn}
                                show={show}
                                curve={curve}
                            />
                        )}
                        {engine === 'elixir' && (
                            <MindElixir
                                ref={elixirRef}
                                root={root}
                                look={look}
                                colorFor={colorFor}
                                textOn={textOn}
                                show={show}
                                openTo={openTo}
                                editable={editable}
                                line={curve ? 'curve' : 'straight'}
                                nodeStyle={nodeStyle}
                                density={dense}
                                direction={direction}
                                alignment={alignment}
                                onPick={onPick}
                            />
                        )}
                        {engine === 'jsmind' && (
                            <JsMindMap
                                ref={jsmindRef}
                                root={root}
                                look={look}
                                colorFor={colorFor}
                                textOn={textOn}
                                show={show}
                                openTo={openTo}
                                editable={editable}
                                nodeStyle={nodeStyle}
                                density={dense}
                                curve={curve}
                                mode={direction === 'side' ? 'full' : 'side'}
                                onPick={onPick}
                            />
                        )}
                    </React.Suspense>
                )}
            </Sheet>
        </Box>
    );
}
